function sumAll(arr) {
  const start = Math.min(...arr);
  const end = Math.max(...arr);
  return Array.from(
    { length: end - start + 1 },
    (_, i) => start + i
  ).reduce((acc, curr) => acc + curr, 0);
}

function sumAll(arr) {
  const min = Math.min(arr[0], arr[1]);
  const max = Math.max(arr[0], arr[1]);
  const count = max - min + 1;
  return (count * (min + max)) / 2;
}

